56	
57	  g_dcmi_init = reinterpret_cast<DcmiInitFunc>(dlsym(g_dcmi_handle, "dcmiv2_init"));
58	  g_dcmi_get_urma_device_cnt =
59	      reinterpret_cast<DcmiGetUrmaDeviceCntFunc>(dlsym(g_dcmi_handle, "dcmiv2_get_urma_device_cnt"));
60	  g_dcmi_get_eid_list =
61	      reinterpret_cast<DcmiGetEidListFunc>(dlsym(g_dcmi_handle, "dcmiv2_get_eid_list_by_urma_dev_index"));
62	  g_dcmi_get_mainboard_id = reinterpret_cast<DcmiGetMainboardIdFunc>(dlsym(g_dcmi_handle, "dcmiv2_get_mainboard_id"));
63	  g_dcmi_get_logicid_from_phyid =
64	      reinterpret_cast<DcmiGetLogicIdFromPhyIdFunc>(dlsym(g_dcmi_handle, "dcmiv2_get_dev_id_by_chip_phy_id"));
65	  if (g_dcmi_get_logicid_from_phyid == nullptr) {
66	    g_dcmi_get_logicid_from_phyid =
67	        reinterpret_cast<DcmiGetLogicIdFromPhyIdFunc>(dlsym(g_dcmi_handle, "dcmiv2_get_dev_id_from_chip_phyid"));
68	  }
69	
70	  g_dcmi_get_device_info = reinterpret_cast<DcmiGetDeviceInfoFunc>(dlsym(g_dcmi_handle, "dcmiv2_get_device_info"));
71	  if (g_dcmi_init == nullptr || g_dcmi_get_urma_device_cnt == nullptr || g_dcmi_get_eid_list == nullptr ||
72	      g_dcmi_get_mainboard_id == nullptr || g_dcmi_get_logicid_from_phyid == nullptr ||
73	      g_dcmi_get_device_info == nullptr) {
74	    HIXL_LOGE(FAILED, "Failed to load DCMI function symbols");
75	    dlclose(g_dcmi_handle);
76	    g_dcmi_handle = nullptr;
