89	      break;
90	    }
91	    sleep(1);
92	  }
93	
94	  if (g_dcmi_init_status != 0) {
95	    HIXL_LOGE(FAILED, "DCMI init failed after %d retries", kMaxWaitTime);
96	    dlclose(g_dcmi_handle);
97	    g_dcmi_handle = nullptr;
98	    g_dcmi_init_status = -1;
99	    return g_dcmi_init_status;
100	  }
101	
102	  return 0;
103	}
