105	int32_t LoadDcmiUnlocked() {
106	  if (g_dcmi_loaded) {
107	    return g_dcmi_init_status;
108	  }
109	
110	  if (TryLoadDcmiSymbols() != 0) {
111	    g_dcmi_init_status = -1;
112	    g_dcmi_loaded = true;
113	    return g_dcmi_init_status;
114	  }
115	
116	  if (InitDcmiWithRetry() != 0) {
117	    g_dcmi_init_status = -1;
118	    g_dcmi_loaded = true;
119	    return g_dcmi_init_status;
120	  }
121	
122	  g_dcmi_loaded = true;
123	  return g_dcmi_init_status;
124	}
