#include "hccp_proxy.h"
#include <chrono>
#include <cstdint>
#include <mutex>
#include <thread>
#include <dlfcn.h>
#include "acl/acl.h"
#include "rt_external_event.h"
#include "common/hixl_checker.h"
#include "common/hixl_log.h"
#include "common/scope_guard.h"

namespace hixl {
namespace {
constexpr int32_t kRoceEagain = 128101;
constexpr const char *kLibRaSo = "libra.so";
// RoCE/HCCS RA notify path is only used for 910B / 910_93-class notify record layout (see HCCL GetNotifySize).
constexpr uint32_t kNotifyRecordByteLengthRa = 4U;

using RdmaHandle = void *;
using RaRdevGetHandleFn = int (*)(unsigned int phy_id, RdmaHandle *out_handle);
using RaGetNotifyBaseAddrFn = int (*)(RdmaHandle handle, unsigned long long *va, unsigned long long *size);

struct LibRaLoader {
  void *handle = nullptr;
  RaRdevGetHandleFn ra_rdev_get_handle = nullptr;
  RaGetNotifyBaseAddrFn ra_get_notify_base_addr = nullptr;
  std::mutex mu;

  ~LibRaLoader() {
    std::lock_guard<std::mutex> lock(mu);
    if (handle != nullptr) {
      HIXL_LOGI("[HccpProxy] LibRaLoader destruct, dlclose %s", kLibRaSo);
      (void)dlclose(handle);
      handle = nullptr;
      ra_rdev_get_handle = nullptr;
      ra_get_notify_base_addr = nullptr;
    }
  }
};

LibRaLoader &LibRa() {
  static LibRaLoader inst;
  return inst;
}

Status EnsureLibRaLoaded() {
  LibRaLoader &lr = LibRa();
  std::lock_guard<std::mutex> lock(lr.mu);
  if (lr.handle != nullptr) {
    return SUCCESS;
  }
  const int32_t dl_mode = static_cast<int32_t>(static_cast<uint32_t>(RTLD_NOW) | static_cast<uint32_t>(RTLD_GLOBAL));
  void *h = dlopen(kLibRaSo, dl_mode);
  const char *open_error = (h == nullptr) ? dlerror() : "";
  HIXL_CHK_BOOL_RET_STATUS(h != nullptr, FAILED, "[HccpProxy] Call api:dlopen failed, lib:%s, msg:%s", kLibRaSo,
                           open_error == nullptr ? "unknown error" : open_error);
  HIXL_DISMISSABLE_GUARD(handle_guard, ([h]() { (void)dlclose(h); }));
  auto *get_handle = reinterpret_cast<RaRdevGetHandleFn>(dlsym(h, "RaRdevGetHandle"));
  auto *get_ba = reinterpret_cast<RaGetNotifyBaseAddrFn>(dlsym(h, "RaGetNotifyBaseAddr"));
  const bool symbols_loaded = get_handle != nullptr && get_ba != nullptr;
  const char *symbol_error = symbols_loaded ? "" : dlerror();
  HIXL_CHK_BOOL_RET_STATUS(symbols_loaded, FAILED,
                           "[HccpProxy] Call api:dlsym failed, symbols:RaRdevGetHandle/RaGetNotifyBaseAddr, msg:%s",
                           symbol_error == nullptr ? "unknown error" : symbol_error);
  lr.handle = h;
  lr.ra_rdev_get_handle = get_handle;
  lr.ra_get_notify_base_addr = get_ba;
  HIXL_DISMISS_GUARD(handle_guard);
  return SUCCESS;
